n.exploreUrl:
@js:
let url = "https://m.whzh-xs.cc"
let arr = []
let push = (title, url, type) => arr.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

let res = org.jsoup.Jsoup.parse(java.ajax(url))
res.select('.nav li').forEach(($) => {
    let text = $.select('a').text();
    let href = url + $.select('a').attr('href');
    push('🔖   '+text+'   🔖', '', 1);
    cate = org.jsoup.Jsoup.parse(java.ajax(href));
    cate.select('.navbar-list li').forEach((c) => {
    let text = c.select('a').text();
    let href = url + c.select('a').attr('href') + '?page={{page}}'; 
    push(text, href, 0.25);
    });
});

JSON.stringify(arr)

